const raw = $input.first().json;
function text(value, label, max, required = true, multiline = false) {
  if (typeof value !== 'string') throw new Error(label + ': ожидается строка');
  const s = value.normalize('NFC').trim();
  if ((required && !s) || [...s].length > max || /[\uD800-\uDFFF]/u.test(s)) throw new Error(label + ': недопустимая длина или Unicode');
  if ((multiline ? /[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/u : /[\u0000-\u001F\u007F]/u).test(s)) throw new Error(label + ': управляющие символы запрещены');
  return s;
}
const client_name = text(raw['Имя'], 'Имя', 120);
const contact = text(raw['Контакт'], 'Контакт', 120);
const email = text(raw['Электронная почта'], 'Email', 254);
if (!/^[A-Za-z0-9.!#$%&'*+/=?^_\x60{|}~-]+@[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?(?:\.[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?)+$/.test(email) || email.startsWith('.') || email.includes('..') || email.split('@')[0].endsWith('.')) throw new Error('Email: укажите один корректный адрес');
const service = text(raw['Услуга'], 'Услуга', 100);
const catalog = {
  'Экспресс-разбор': {product_slug: 'express-review', amount: '4900.00'},
  'AI-аудит процесса': {product_slug: 'ai-audit', amount: '14900.00'}
};
if (!Object.hasOwn(catalog, service)) throw new Error('Услуга отсутствует в фиксированном каталоге');
const amountInput = String(raw['Сумма'] ?? '').trim();
if (!/^(?:0|[1-9]\d{0,7})(?:[.,]\d{1,2})?$/.test(amountInput)) throw new Error('Сумма: нужен положительный денежный формат с точностью до копеек');
const parts = amountInput.replace(',', '.').split('.');
const amount = parts[0] + '.' + (parts[1] || '').padEnd(2, '0');
if (amount !== catalog[service].amount) throw new Error('Сумма не совпадает с ценой выбранной услуги: ' + catalog[service].amount);
const comment = text(raw['Комментарий клиента'] ?? '', 'Комментарий', 2000, false, true);
if (typeof raw.submittedAt !== 'string' || !/^\d{4}-\d{2}-\d{2}T.*(?:Z|[+-]\d{2}:\d{2})$/.test(raw.submittedAt) || !Number.isFinite(Date.parse(raw.submittedAt))) throw new Error('Нет корректного submittedAt от Form Trigger: отправьте форму заново');
const submitted_at = new Date(raw.submittedAt).toISOString();
const product_slug = catalog[service].product_slug;
const request_fingerprint = JSON.stringify({version: 'NNS_09_v1', submitted_at, client_name, contact, email, service, amount, comment});
return [{json: {client_name, contact, email, service, product_slug, amount, comment, submitted_at, request_fingerprint}}];

const original = $('ID заявки').first().json;
if (!/^[a-f0-9]{64}$/.test(original.request_id || '')) throw new Error('Нет стабильного request_id');
const api = $input.first().json;
const choice = api.choices?.[0];
if (api.error || !choice || choice.finish_reason !== 'stop' || choice.message?.refusal || choice.message?.tool_calls) throw new Error('ИИ не вернул завершённый ответ: платёжный заказ не создавался');
const content = choice.message?.content;
if (typeof content !== 'string' || content.length > 15000) throw new Error('Некорректный формат ответа ИИ');
let analysis;
try { analysis = JSON.parse(content); } catch { throw new Error('Ответ ИИ не является JSON'); }
const fields = ['client_name','request_type','request_summary','payment_description','amount','priority'];
if (!analysis || Array.isArray(analysis) || typeof analysis !== 'object' || Object.keys(analysis).length !== fields.length || fields.some(k => !Object.hasOwn(analysis, k))) throw new Error('JSON ИИ должен содержать ровно шесть согласованных полей');
const limits = {client_name:120, request_type:80, request_summary:1000, payment_description:200, amount:20, priority:20};
for (const key of fields) {
  const s = analysis[key];
  if (typeof s !== 'string' || !s.trim() || s !== s.trim() || [...s].length > limits[key] || /[\u0000-\u001F\u007F\uD800-\uDFFF]/u.test(s) || /(?:https?:\/\/|www\.|javascript:|data:|<|>)/iu.test(s)) throw new Error('Недопустимое поле ИИ: ' + key);
}
if (analysis.client_name !== original.client_name) throw new Error('ИИ изменил имя клиента');
if (analysis.request_type !== original.service) throw new Error('ИИ изменил тип выбранной услуги');
if (analysis.amount !== original.amount) throw new Error('ИИ изменил сумму: заказ не создавался');
if (!['low','normal','high'].includes(analysis.priority)) throw new Error('Недопустимый приоритет ИИ');
const portal_payload = {
  request_id: original.request_id,
  product_slug: original.product_slug,
  amount: original.amount,
  name: original.client_name,
  email: original.email,
  contact: original.contact,
  comment: original.comment,
  analysis
};
return [{json: {
  request_id: original.request_id, date: original.submitted_at,
  client_name: original.client_name, contact: original.contact, email: original.email,
  product_slug: original.product_slug, ...analysis,
  status: 'Формируется ссылка', payment_link: '', order_id: '', notification_status: 'not_queued',
  portal_payload
}}];

const expected = $('Проверить JSON ИИ').first().json;
const result = $input.first().json;
if (!result || result.request_id !== expected.request_id || result.product_slug !== expected.product_slug || result.amount !== expected.amount) throw new Error('Ответ портала не совпадает с исходной заявкой');
if (!Number.isSafeInteger(result.order_id) || result.order_id <= 0) throw new Error('Портал не вернул корректный номер заказа');
if (typeof result.payment_link !== 'string' || !/^https:\/\/st8dom\.ru\/orders\/pay\/[A-Za-z0-9_-]{43}\/$/.test(result.payment_link)) throw new Error('Портал вернул недопустимый адрес оплаты');
const states = {
  new: 'Ожидает оплату', payment_pending: 'Ожидает оплату', payment_failed: 'Ожидает оплату',
  paid: 'Оплачен', refund_processing: 'Возврат обрабатывается', refund_failed: 'Ошибка возврата',
  refunded: 'Возвращён'
};
if (!Object.hasOwn(states, result.status)) throw new Error('Неизвестный статус заказа от портала');
const mailStates = ['not_queued','pending','sending','sent','failed','unknown','cancelled'];
if (!mailStates.includes(result.notification_status)) throw new Error('Неизвестный статус уведомления от портала');
return [{json: {
  ...expected, order_id: String(result.order_id), payment_link: result.payment_link,
  status: states[result.status], portal_status: result.status,
  notification_status: result.notification_status
}}];

const order = $('Проверить платёжную ссылку').first().json;
const result = $input.first().json;
if (!result || result.request_id !== order.request_id || String(result.order_id) !== order.order_id || result.product_slug !== order.product_slug || result.amount !== order.amount || result.payment_link !== order.payment_link) throw new Error('Уведомление относится к другому заказу: проверьте исполнение');
if (result.status !== order.portal_status) throw new Error('Статус заказа изменился: проверьте состояние на портале');
const mail = result.notification_status;
if (!['pending','sending','sent'].includes(mail)) throw new Error('Письмо не подтверждено к отправке: ' + String(mail) + '. Заказ сохранён; не повторяйте отправку вслепую');
const mailText = mail === 'sent'
  ? 'Почтовый сервер принял письмо. Проверьте «Входящие» и «Спам».'
  : 'Письмо поставлено в очередь. Проверьте почту через 1–2 минуты.';
const completion_message = 'Заказ №' + order.order_id + ' сохранён. <a href="' + order.payment_link + '">Открыть ссылку для оплаты</a>. ' + mailText + ' Для учебной проверки оплачивать заказ не требуется.';
return [{json: {...order, notification_status: mail, completion_message}}];
